mapper.select:
select

from
settle_trans_data std
WHERE
1=1

	AND std.TRADE_ID = #{tradeId, jdbcType=VARCHAR}


	AND std.APPLY_TRADE_ID = #{applyTradeId, jdbcType=VARCHAR}


	AND std.FINPROD_ID = #{finprodId, jdbcType=VARCHAR}


	AND std.DEAL_DATE = #{dealDate, jdbcType=DATE}


	AND std.SEAT_NUMBER = #{seatNumber, jdbcType=VARCHAR}


	AND std.CJBH = #{cjbh, jdbcType=VARCHAR}


	AND std.SEC_ACCT_ID = #{secAcctId, jdbcType=VARCHAR}


	AND std.TRADE_DATE = #{tradeDate, jdbcType=DATE}


	AND std.PS = #{ps, jdbcType=VARCHAR}

order by std.SHARE_AMT desc

